-- Step 3.1 (2026-09-18): Bokun customer price in its own columns.
-- tours.paid / payment_status / total_amount_paid / expected_amount are LOCAL state (guide payment
-- tracking); the Bokun sync no longer writes them on UPDATE. What the customer paid goes here.
-- Self-provisioned by ensureBokunPriceColumns() in public_html/api/bokun_sync.php (same statements),
-- so neither environment needs this file to be run by hand. Idempotent.

ALTER TABLE tours
    ADD COLUMN IF NOT EXISTS `bokun_total_price` DECIMAL(10,2) NULL DEFAULT NULL AFTER `expected_amount`,
    ADD COLUMN IF NOT EXISTS `bokun_currency` VARCHAR(3) NULL DEFAULT NULL AFTER `bokun_total_price`;

-- Backfill from the stored Bokun JSON (generated by bokunPriceBackfillSql(); same paths and order as
-- bokunCustomerPrice() in tour_classification.php). Only touches rows that have no price yet.
UPDATE tours
    SET bokun_total_price = ROUND(COALESCE(JSON_UNQUOTE(JSON_EXTRACT(bokun_data, '$.resellerInvoice.total')), JSON_UNQUOTE(JSON_EXTRACT(bokun_data, '$.productBookings[0].resellerInvoice.total')), JSON_UNQUOTE(JSON_EXTRACT(bokun_data, '$.activityBookings[0].resellerInvoice.total')), JSON_UNQUOTE(JSON_EXTRACT(bokun_data, '$.customerInvoice.total')), JSON_UNQUOTE(JSON_EXTRACT(bokun_data, '$.productBookings[0].customerInvoice.total')), JSON_UNQUOTE(JSON_EXTRACT(bokun_data, '$.activityBookings[0].customerInvoice.total')), NULLIF((JSON_UNQUOTE(JSON_EXTRACT(bokun_data, '$.totalPrice')) + 0), 0), NULLIF((JSON_UNQUOTE(JSON_EXTRACT(bokun_data, '$.productBookings[0].totalPrice')) + 0), 0), NULLIF((JSON_UNQUOTE(JSON_EXTRACT(bokun_data, '$.activityBookings[0].totalPrice')) + 0), 0)), 2),
    bokun_currency = UPPER(LEFT(COALESCE(IF(JSON_EXTRACT(bokun_data, '$.resellerInvoice.total') IS NULL, NULL, COALESCE(JSON_UNQUOTE(JSON_EXTRACT(bokun_data, '$.resellerInvoice.currency')), JSON_UNQUOTE(JSON_EXTRACT(bokun_data, '$.currency')), JSON_UNQUOTE(JSON_EXTRACT(bokun_data, '$.currency')))), IF(JSON_EXTRACT(bokun_data, '$.productBookings[0].resellerInvoice.total') IS NULL, NULL, COALESCE(JSON_UNQUOTE(JSON_EXTRACT(bokun_data, '$.productBookings[0].resellerInvoice.currency')), JSON_UNQUOTE(JSON_EXTRACT(bokun_data, '$.productBookings[0].currency')), JSON_UNQUOTE(JSON_EXTRACT(bokun_data, '$.currency')))), IF(JSON_EXTRACT(bokun_data, '$.activityBookings[0].resellerInvoice.total') IS NULL, NULL, COALESCE(JSON_UNQUOTE(JSON_EXTRACT(bokun_data, '$.activityBookings[0].resellerInvoice.currency')), JSON_UNQUOTE(JSON_EXTRACT(bokun_data, '$.activityBookings[0].currency')), JSON_UNQUOTE(JSON_EXTRACT(bokun_data, '$.currency')))), IF(JSON_EXTRACT(bokun_data, '$.customerInvoice.total') IS NULL, NULL, COALESCE(JSON_UNQUOTE(JSON_EXTRACT(bokun_data, '$.customerInvoice.currency')), JSON_UNQUOTE(JSON_EXTRACT(bokun_data, '$.currency')), JSON_UNQUOTE(JSON_EXTRACT(bokun_data, '$.currency')))), IF(JSON_EXTRACT(bokun_data, '$.productBookings[0].customerInvoice.total') IS NULL, NULL, COALESCE(JSON_UNQUOTE(JSON_EXTRACT(bokun_data, '$.productBookings[0].customerInvoice.currency')), JSON_UNQUOTE(JSON_EXTRACT(bokun_data, '$.productBookings[0].currency')), JSON_UNQUOTE(JSON_EXTRACT(bokun_data, '$.currency')))), IF(JSON_EXTRACT(bokun_data, '$.activityBookings[0].customerInvoice.total') IS NULL, NULL, COALESCE(JSON_UNQUOTE(JSON_EXTRACT(bokun_data, '$.activityBookings[0].customerInvoice.currency')), JSON_UNQUOTE(JSON_EXTRACT(bokun_data, '$.activityBookings[0].currency')), JSON_UNQUOTE(JSON_EXTRACT(bokun_data, '$.currency')))), IF(COALESCE((JSON_UNQUOTE(JSON_EXTRACT(bokun_data, '$.totalPrice')) + 0), 0) = 0, NULL, COALESCE(JSON_UNQUOTE(JSON_EXTRACT(bokun_data, '$.currency')), JSON_UNQUOTE(JSON_EXTRACT(bokun_data, '$.currency')))), IF(COALESCE((JSON_UNQUOTE(JSON_EXTRACT(bokun_data, '$.productBookings[0].totalPrice')) + 0), 0) = 0, NULL, COALESCE(JSON_UNQUOTE(JSON_EXTRACT(bokun_data, '$.productBookings[0].currency')), JSON_UNQUOTE(JSON_EXTRACT(bokun_data, '$.currency')))), IF(COALESCE((JSON_UNQUOTE(JSON_EXTRACT(bokun_data, '$.activityBookings[0].totalPrice')) + 0), 0) = 0, NULL, COALESCE(JSON_UNQUOTE(JSON_EXTRACT(bokun_data, '$.activityBookings[0].currency')), JSON_UNQUOTE(JSON_EXTRACT(bokun_data, '$.currency'))))), 3))
    WHERE bokun_total_price IS NULL
    AND bokun_data IS NOT NULL AND JSON_VALID(bokun_data)
    AND COALESCE(JSON_UNQUOTE(JSON_EXTRACT(bokun_data, '$.resellerInvoice.total')), JSON_UNQUOTE(JSON_EXTRACT(bokun_data, '$.productBookings[0].resellerInvoice.total')), JSON_UNQUOTE(JSON_EXTRACT(bokun_data, '$.activityBookings[0].resellerInvoice.total')), JSON_UNQUOTE(JSON_EXTRACT(bokun_data, '$.customerInvoice.total')), JSON_UNQUOTE(JSON_EXTRACT(bokun_data, '$.productBookings[0].customerInvoice.total')), JSON_UNQUOTE(JSON_EXTRACT(bokun_data, '$.activityBookings[0].customerInvoice.total')), NULLIF((JSON_UNQUOTE(JSON_EXTRACT(bokun_data, '$.totalPrice')) + 0), 0), NULLIF((JSON_UNQUOTE(JSON_EXTRACT(bokun_data, '$.productBookings[0].totalPrice')) + 0), 0), NULLIF((JSON_UNQUOTE(JSON_EXTRACT(bokun_data, '$.activityBookings[0].totalPrice')) + 0), 0)) IS NOT NULL;
